import SwiftUI
struct SettingsView:View{
 @EnvironmentObject var config:DVRConfigStore
 var body:some View{NavigationStack{Form{Section("DVR"){TextField("DVR host / external address",text:$config.host).textInputAutocapitalization(.never).autocorrectionDisabled();TextField("RTSP port",text:$config.rtspPort).keyboardType(.numberPad);TextField("Web port",text:$config.webPort).keyboardType(.numberPad);TextField("Username",text:$config.username);SecureField("Password",text:$config.password)};Section("RTSP template"){TextField("rtsp://...",text:$config.rtspTemplate,axis:.vertical).textInputAutocapitalization(.never).autocorrectionDisabled();Text("Variables: {host} {port} {channel} {username} {password} {stream}").font(.footnote).foregroundStyle(.secondary)};Section("Kestrel web"){TextField("Playback path",text:$config.playbackPath);Text("Known web interface: port 8081, Preview/Playback, CAM 1–16, Main/Sub, LocalPlayback and processbar.").font(.footnote).foregroundStyle(.secondary)};Section("Capacity"){Text("16 channels; current system has 5 cameras. Audio, archive audio and two-way talk remain protocol capabilities.").font(.footnote)}}.navigationTitle("Settings")}}
